    mut d: *mut tdefl_compressor,
    mut lookahead_pos: mz_uint,
    mut max_dist: mz_uint,
    mut max_match_len: mz_uint,
    mut pMatch_dist: *mut mz_uint,
    mut pMatch_len: *mut mz_uint,
