    let pos: mz_uint = lookahead_pos & TDEFL_LZ_DICT_SIZE_MASK as c_int as mz_uint;
    let mut match_len: mz_uint = *pMatch_len;
    if max_match_len <= match_len {
        return;
    }

    let dict = &(*d).m_dict;
    let next = &(*d).m_next;

    let mut probe_pos: mz_uint = pos;
    let mut dist: mz_uint;
    let mut num_probes_left: mz_uint =
        (*d).m_max_probes[(match_len >= 32 as mz_uint) as c_int as usize];

    let s = dict.as_ptr().wrapping_add(pos as usize);
    let mut c0: mz_uint8 = dict[pos.wrapping_add(match_len) as usize];
    let mut c1: mz_uint8 = dict[pos.wrapping_add(match_len).wrapping_sub(1 as mz_uint) as usize];

    loop {
        let found_probe = loop {
            num_probes_left = num_probes_left.wrapping_sub(1);
            if num_probes_left == 0 {
                return;
            }
            let mut next_probe_pos = next[probe_pos as usize] as mz_uint;
            if next_probe_pos == 0 {
                return;
            }
            dist = lookahead_pos.wrapping_sub(next_probe_pos) as mz_uint16 as mz_uint;
            if dist > max_dist {
                return;
            }
            probe_pos = next_probe_pos & TDEFL_LZ_DICT_SIZE_MASK as c_int as mz_uint;
            let probe_idx = probe_pos.wrapping_add(match_len) as usize;
            if dict[probe_idx] == c0 && dict[probe_idx - 1] == c1 {
                break true;
            }

            num_probes_left = num_probes_left.wrapping_sub(1);
            if num_probes_left == 0 {
                return;
            }
            next_probe_pos = next[probe_pos as usize] as mz_uint;
            if next_probe_pos == 0 {
                return;
            }
            dist = lookahead_pos.wrapping_sub(next_probe_pos) as mz_uint16 as mz_uint;
            if dist > max_dist {
                return;
            }
            probe_pos = next_probe_pos & TDEFL_LZ_DICT_SIZE_MASK as c_int as mz_uint;
            let probe_idx = probe_pos.wrapping_add(match_len) as usize;
            if dict[probe_idx] == c0 && dict[probe_idx - 1] == c1 {
                break true;
            }

            num_probes_left = num_probes_left.wrapping_sub(1);
            if num_probes_left == 0 {
                return;
            }
            next_probe_pos = next[probe_pos as usize] as mz_uint;
            if next_probe_pos == 0 {
                return;
            }
            dist = lookahead_pos.wrapping_sub(next_probe_pos) as mz_uint16 as mz_uint;
            if dist > max_dist {
                return;
            }
            probe_pos = next_probe_pos & TDEFL_LZ_DICT_SIZE_MASK as c_int as mz_uint;
            let probe_idx = probe_pos.wrapping_add(match_len) as usize;
            if dict[probe_idx] == c0 && dict[probe_idx - 1] == c1 {
                break true;
            }
        };

        if !found_probe {
            return;
        }

        let q = dict.as_ptr().wrapping_add(probe_pos as usize);
        let mut probe_len: mz_uint = 0;

        while probe_len < max_match_len {
            // SAFETY: `s` points into `m_dict` at `pos`, `q` points into `m_dict` at `probe_pos`,
            // and the original function relies on accesses up to `max_match_len` within `m_dict`.
            let a = unsafe { *s.add(probe_len as usize) };
            // SAFETY: Same preconditions as above; `q.add(probe_len)` stays within the same valid range.
            let b = unsafe { *q.add(probe_len as usize) };
            if a != b {
                break;
            }
            probe_len = probe_len.wrapping_add(1);
        }

        if probe_len > match_len {
            *pMatch_dist = dist;
            match_len = probe_len;
            *pMatch_len = match_len;
            if match_len == max_match_len {
                return;
            }
            c0 = dict[pos.wrapping_add(match_len) as usize];
            c1 = dict[pos.wrapping_add(match_len).wrapping_sub(1 as mz_uint) as usize];
        }
    }
}

